create extension if not exists pgcrypto;
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,email text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.user_vault(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,label text not null check(char_length(label) between 1 and 120),variable_name text not null check(char_length(variable_name) between 1 and 120),encrypted_value jsonb not null,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
alter table public.profiles enable row level security;alter table public.user_vault enable row level security;
drop policy if exists "profiles_self" on public.profiles;create policy "profiles_self" on public.profiles for all using(auth.uid()=id) with check(auth.uid()=id);
drop policy if exists "vault_self" on public.user_vault;create policy "vault_self" on public.user_vault for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,email) values(new.id,new.email) on conflict(id) do update set email=excluded.email; return new; end; $$;
drop trigger if exists on_auth_user_created on auth.users;create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
create or replace function public.set_updated_at() returns trigger language plpgsql as $$ begin new.updated_at=now();return new;end;$$;
drop trigger if exists profiles_updated_at on public.profiles;create trigger profiles_updated_at before update on public.profiles for each row execute procedure public.set_updated_at();
drop trigger if exists vault_updated_at on public.user_vault;create trigger vault_updated_at before update on public.user_vault for each row execute procedure public.set_updated_at();
revoke all on table public.profiles,public.user_vault from anon;grant select,insert,update,delete on table public.profiles,public.user_vault to authenticated;
